#!/usr/bin/env python3
from __future__ import annotations
import argparse, base64, hashlib, json, py_compile, shutil
from datetime import datetime
from pathlib import Path
FILES = {
  "configs/polarimetric_representation_benchmark_v2.yaml": "",
  "datasets/polarimetric_detection_dataset_v2.py": "",
  "features/polarimetric_gated_rd.py": "",
  "scripts/audit_polarimetric_channels_v1.py": "",
  "scripts/audit_polarimetric_score_shift_v1.py": "",
  "scripts/run_polarimetric_representation_benchmark_v2.py": "",
  "scripts/summarize_polarimetric_representation_benchmark_v2.py": "",
  "scripts/test_polarimetric_gated_pipeline_v2.py": "",
  "training/train_polarimetric_representation_fcn_v2.py": ""
}
HASHES = {
  "configs/polarimetric_representation_benchmark_v2.yaml": "66c04346f6690aaf7deef7950d1b29ea0f69767b89e1373873d3b57540a5aef8",
  "datasets/polarimetric_detection_dataset_v2.py": "ef3bc15a370ae74c0f1e80765136ab338eedd17029f900e4ee709edf8df2ca5d",
  "features/polarimetric_gated_rd.py": "fca8e3f0c76848ca87d999a8a73c669780b4ae3a26ecf53b477c91c3a2d99656",
  "scripts/audit_polarimetric_channels_v1.py": "76c6a14d8a0be1e6c32cee2b80d0edecbc54b512b11aec9e7bf702ab2891d078",
  "scripts/audit_polarimetric_score_shift_v1.py": "3fd207823fdeb3bdeadebdf1df1cb658f508915297458399cc37c3857e11cba1",
  "scripts/run_polarimetric_representation_benchmark_v2.py": "c66b92941432f0288dbddad354d5c86460bfc1de8e44ead4cf57f21fda5380e9",
  "scripts/summarize_polarimetric_representation_benchmark_v2.py": "a6b6fc495eae0a0a349c750991002681d1b0ee5976825bea64efbad980458f93",
  "scripts/test_polarimetric_gated_pipeline_v2.py": "1298cc7abcebb2ebbf6f755c39a9301d49be17581a04635d08ac5c11e110d0e1",
  "training/train_polarimetric_representation_fcn_v2.py": "8fafc9c79af32e126642b1e3410e1fb78e5ecb12651caaf493eac52a984b7ee4"
}
REQUIRED = (
    "features/polarimetric_rd.py",
    "models/polarimetric_representation_fcn.py",
    "models/simple_fcn.py",
    "scripts/train_detection_baseline_v2.py",
    "datasets/detection_dataset_v2.py",
)
def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()
def main() -> None:
    parser = argparse.ArgumentParser(description="Install gated polarimetric representation benchmark v2")
    parser.add_argument("--dry-run", action="store_true")
    args = parser.parse_args()
    project_root = Path(__file__).resolve().parent
    missing = [x for x in REQUIRED if not (project_root / x).is_file()]
    if missing:
        print("[错误] 请把安装脚本直接放在 balloon_radar_project 项目根目录。")
        for x in missing:
            print("  - 缺少", x)
        raise SystemExit(2)
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_root = project_root / "backups" / f"polarimetric_gated_representation_v2_{stamp}"
    installed, skipped, backed = [], [], []
    for rel, encoded in FILES.items():
        content = base64.b64decode(encoded)
        if sha256(content) != HASHES[rel]:
            raise RuntimeError(f"内置哈希校验失败: {rel}")
        target = project_root / rel
        if target.is_file() and sha256(target.read_bytes()) == HASHES[rel]:
            skipped.append(rel)
            print("[跳过] 已是目标版本:", rel)
            continue
        if args.dry_run:
            print("[预览] 将写入:", rel)
            continue
        if target.exists():
            backup = backup_root / rel
            backup.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(target, backup)
            backed.append(rel)
            print("[备份]", rel)
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(content)
        installed.append(rel)
        print("[写入]", rel)
    if args.dry_run:
        return
    for rel in FILES:
        if rel.endswith(".py"):
            py_compile.compile(str(project_root / rel), doraise=True)
            print("[语法通过]", rel)
    record_dir = project_root / "results/data_audit/polarimetric_representation_benchmark_v2"
    record_dir.mkdir(parents=True, exist_ok=True)
    record = {
        "installed_at": datetime.now().isoformat(),
        "project_root": str(project_root),
        "installed_files": installed,
        "skipped_identical_files": skipped,
        "backed_up_files": backed,
        "backup_root": str(backup_root) if backed else None,
        "hashes": HASHES,
    }
    (record_dir / "install_record.json").write_text(
        json.dumps(record, ensure_ascii=False, indent=2), encoding="utf-8"
    )
    print("\n" + "=" * 88)
    print("安装完成：显式极化门控与分数迁移诊断 V2")
    print("先运行诊断与管线测试，再运行两折 smoke。")
    print("=" * 88)
if __name__ == "__main__":
    main()
